const body = $json.body || $json;
const sender = body.sender || body.from || body.phone || '';
const messageText = (body.message || body.text || '').trim().toLowerCase();

let status = 'Belum Konfirmasi';
if (messageText.includes('hadir') && !messageText.includes('tidak')) {
  status = 'Hadir';
} else if (messageText.includes('tidak hadir') || messageText.includes('tidak')) {
  status = 'Tidak Hadir';
}

// Normalisasi nomor WA (hilangkan +, @c.us, dll)
const cleanPhone = sender.replace(/[^0-9]/g, '');

return {
  json: {
    nomor_wa_clean: cleanPhone,
    pesan_diterima: messageText,
    status_kehadiran: status,
    waktu_balas: new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' })
  }
};
